class _SocketFile:
    """
    There are several operations that may run faster in case it is known what is the underlying
    data format and the type of communication.

    The class may act as both BufferedReader and BufferedWriter (writer path is implemented only
    to avoid massive code changes)

    The optimizations added:
    1. open_arrow_stream() - creates a stream of RecordBatches that are restored from network data
    by using native arrow recovery. It is much more efficient than python library call, as does
    less memory allocations.
    2. set_read_timeout() - allows to utilize read timeout for streaming use cases, where the read
    of next record may be interrupted and special "empty" record is issued to trigger write of
    pre-accumulated data.
    """

    def __init__(self,
                 input: "io.BufferedReader", output: "io.BufferedWriter",
                 sock, create_buffer_copy: bool) -> None:
        """
        Parameters
        ----------
        input : io.BufferedReader
            Readable file-like object backed by the socket fd.
        output : io.BufferedWriter
            Writable file-like object for the same socket. This instance also acts as a
            writer (write/flush), allowing it to replace the original sock_file without
            additional plumbing.
        sock : socket.socket
            The underlying socket, used for setting SO_RCVTIMEO via set_read_timeout().
        create_buffer_copy : bool
            If True, a Python bytes copy is made before each batch is decoded, which is
            safer when the caller retains references to previous batches. If False,
            open_arrow_stream() hands the internal PyArrow buffer directly to
            record-batch recovery (zero-copy).
        """
        import pyarrow as pa
        import socket as socket_module
        import struct

        self._socket_module = socket_module
        self._struct = struct
        self._pa = pa

        self._input = input
        self._output = output
        self._sock = sock
        self._create_buffer_copy = create_buffer_copy

        # Read buffer vars.
        # Read buffer position is maintained by 2 pointers:
        #   _read_pos - actual reader position.
        #   _valid_data_pos - till which index _buffer is filled with correct data.
        # The latter one is used for cases when the read process was interrupted and
        # should be restarted.
        self._read_pos = 0
        self._valid_data_pos = 0
        self._buffer = pa.allocate_buffer(10)
        self._mv = memoryview(self._buffer)

    def read(self, n) -> bytes:
        self._read_more(n)
        return self._mark_copy() # intentional copy

    def _read_more(self, bytes_needed) -> memoryview:
        """
        Reads more data from the input stream if needed and returns memory view of
        data read. The size of the returned data is always equal to bytes_needed.
        In case data is already (partially) available, it will be immediately returned.

        The buffer is accumulated internally, and after the call _read_pos is incremented
        by the bytes_needed.
        :param bytes_needed: Bytes to get after self._reader_position
        :return: memory view of the data read, always is bytes_needed in size.
        """
        expected_pos = self._read_pos + bytes_needed
        # Need to make buffer bigger.
        if len(self._buffer) < expected_pos:
            buff2 = self._pa.allocate_buffer(expected_pos)
            mv2 = memoryview(buff2)
            mv2[0:self._valid_data_pos] = self._mv[0:self._valid_data_pos]
            self._buffer, self._mv = buff2, mv2

        while self._valid_data_pos < expected_pos:
            actually_read = self._input.readinto(self._mv[self._valid_data_pos:expected_pos])
            # in case read_timeout is set the method may return None, meaning that the
            # read timeout (SO_RCVTIMEO) was triggered.
            if actually_read is None:
                raise BlockingIOError("read timed out")
            if actually_read == 0:
                raise EOFError("Unexpected end of stream")
            self._valid_data_pos += actually_read
        self._read_pos = expected_pos
        return self._mv[self._read_pos - bytes_needed: expected_pos]

    def _mark(self) -> "Union[pa.Buffer, bytes]":
        """
        Resets reader position to 0. Depending on configuration may create a copy of the buffer.
        :return: pa.Buffer when create_buffer_copy is False (zero-copy), bytes otherwise.
        """
        if not self._create_buffer_copy:
            self._read_pos = 0
            self._valid_data_pos = 0
            return self._buffer
        else:
            return self._mark_copy()

    def _mark_copy(self) -> bytes:
        result = bytes(self._mv[:self._read_pos])
        self._read_pos = 0
        self._valid_data_pos = 0
        return result

    def set_read_timeout(self, timeout_ms):
        """
        Sets read timeout for the input. That means that open_arrow_stream may generate None records
        when the read timeout elapsed.

        Important: do not arm the timeout before the first batch has been yielded by
        open_arrow_stream(). The schema read during stream initialization is not guarded
        against BlockingIOError; a premature timeout would propagate as an unhandled exception.

        :param timeout_ms: Timeout in ms for read operation.
        """
        secs = timeout_ms // 1000
        usecs = (timeout_ms % 1000) * 1000
        self._sock.setsockopt(
            self._socket_module.SOL_SOCKET,
            self._socket_module.SO_RCVTIMEO,
            self._struct.pack("ll", secs, usecs),
        )

    def open_arrow_stream(self):
        """
        Creates a generator that yields arrow RecordBatch(es). After first batch was yielded it is
        possible to call set_read_timeout() to generate empty (None) records.
        """
        pa = self._pa
        struct = self._struct

        def _parse_body_length(meta_bytes):
            root = struct.unpack_from("<I", meta_bytes, 0)[0]
            soffset = struct.unpack_from("<i", meta_bytes, root)[0]
            vtable = root - soffset  # FlatBuffers: vtable is at table_address - soffset
            vtable_size = struct.unpack_from("<H", meta_bytes, vtable)[0]
            if vtable_size < 12 or vtable + 12 > len(meta_bytes):
                return 0
            field_off = struct.unpack_from("<H", meta_bytes, vtable + 10)[0]
            if field_off == 0:
                return 0
            return struct.unpack_from("<q", meta_bytes, root + field_off)[0]

        def _read_header_metadata_length():
            # reads header and returns its length (metadata length)
            h1 = self._read_more(4)
            marker = struct.unpack_from("<I", h1, 0)[0]
            if marker == 0xFFFFFFFF:
                h2 = self._read_more(4)
                return struct.unpack_from("<I", h2, 0)[0]
            else:
                return marker

        # just skip the metadata
        self._read_more(_read_header_metadata_length())
        # mark currently read buffer and recover schema into a separate array (done once, so we could copy)
        schema = pa.ipc.read_schema(pa.ipc.read_message(pa.py_buffer(self._mark_copy())))

        while True:
            # Reset only _read_pos, not _valid_data_pos: on a timed-out read the
            # buffer already holds partially-received bytes that are still valid.
            # Resetting _read_pos replays the batch parse from the start while
            # _valid_data_pos lets _read_more() skip re-fetching those bytes.
            self._read_pos = 0
            try:
                meta_len = _read_header_metadata_length()
                if meta_len == 0:
                    self._mark()
                    break  # EOS marker
                body_length = _parse_body_length(self._read_more(meta_len))
                self._read_more(body_length)
            except BlockingIOError:
                self._read_pos = 0
                yield None
                continue

            msg_bytes = self._mark()
            yield pa.ipc.read_record_batch(pa.py_buffer(msg_bytes), schema)

    def readable(self) -> bool:
        return self._input.readable()

    def write(self, data) -> int:
        return self._output.write(data)

    def flush(self) -> None:
        self._output.flush()

    def writable(self) -> bool:
        return self._output is not None

    @property
    def closed(self) -> bool:
        return self._input.closed

    def close(self) -> None:
        self._input.close()
        if self._output is not None:
            self._output.close()
# END-EDGE


def local_connect_and_auth(
    conn_info: Optional[Union[str, int]], auth_secret: Optional[str]
) -> Tuple:
    """
    Connect to local host, authenticate with it, and return a (sockfile,sock) for that connection.
    Handles IPV4 & IPV6, does some error handling.

    Parameters
    ----------
    port : str or int, optional
    auth_secret : str, optional

    Returns
    -------
    tuple
        with (sockfile, sock)
    """
    buf_size = int(os.environ.get("SPARK_BUFFER_SIZE", 65536))

    is_unix_domain_socket = isinstance(conn_info, str) and auth_secret is None
    if is_unix_domain_socket:
        sock_path = conn_info
        assert isinstance(sock_path, str)
        sock = None
        try:
            sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            sock.settimeout(int(os.environ.get("SPARK_AUTH_SOCKET_TIMEOUT", 15)))
            sock.connect(sock_path)
            sockfile = sock.makefile("rwb", buf_size)
            return (sockfile, sock)
        except socket.error as e:
            if sock is not None:
                sock.close()
            raise PySparkRuntimeError(
                errorClass="CANNOT_OPEN_SOCKET",
                messageParameters={
                    "errors": "tried to connect to %s, but an error occurred: %s"
                    % (sock_path, str(e)),
                },
            )

    sock = None
    errors = []
    # Support for both IPv4 and IPv6.
    addr = "127.0.0.1"
    if os.environ.get("SPARK_PREFER_IPV6", "false").lower() == "true":
        addr = "::1"
    for res in socket.getaddrinfo(addr, conn_info, socket.AF_UNSPEC, socket.SOCK_STREAM):
        af, socktype, proto, _, sa = res
        try:
            sock = socket.socket(af, socktype, proto)
            sock.settimeout(int(os.environ.get("SPARK_AUTH_SOCKET_TIMEOUT", 15)))
            sock.connect(sa)
            sockfile = sock.makefile("rwb", buf_size)
            assert isinstance(auth_secret, str)
            _do_server_auth(sockfile, auth_secret)
            return (sockfile, sock)
        except socket.error as e:
            emsg = str(e)
            errors.append("tried to connect to %s, but an error occurred: %s" % (sa, emsg))
            if sock is not None:
                sock.close()
                sock = None
    raise PySparkRuntimeError(
        errorClass="CANNOT_OPEN_SOCKET",
        messageParameters={
            "errors": str(errors),
        },
    )


def _do_server_auth(conn: "io.IOBase", auth_secret: str) -> None:
    """
    Performs the authentication protocol defined by the SocketAuthHelper class on the given
    file-like object 'conn'.
    """
    write_with_length(auth_secret.encode("utf-8"), conn)
    conn.flush()
    reply = UTF8Deserializer().loads(conn)
    if reply != "ok":
        conn.close()
        raise PySparkRuntimeError(
            errorClass="UNEXPECTED_RESPONSE_FROM_SERVER",
            messageParameters={},
        )


@contextlib.contextmanager
def disable_gc() -> Generator[None, None, None]:
    gc_enabled_originally = gc.isenabled()
    if gc_enabled_originally:
        gc.disable()
    try:
        yield
    finally:
        if gc_enabled_originally:
            gc.enable()


_is_remote_only = None


def is_remote_only() -> bool:
    """
    Returns if the current running environment is only for Spark Connect.
    If users install pyspark-client alone, RDD API does not exist.

    .. versionadded:: 4.0.0

    Notes
    -----
    This will only return ``True`` if installed PySpark is only for Spark Connect.
    Otherwise, it returns ``False``.

    This API is unstable, and for developers.

    Returns
    -------
    bool

    Examples
    --------
    >>> from pyspark.sql import is_remote
    >>> is_remote()
    False
    """
    global _is_remote_only

    if "SPARK_SKIP_CONNECT_COMPAT_TESTS" in os.environ:
        return True

    if _is_remote_only is not None:
        return _is_remote_only
    try:
        from pyspark import core  # noqa: F401

        _is_remote_only = False
        return _is_remote_only
    except ImportError:
        _is_remote_only = True
        return _is_remote_only


