def is_uc() -> bool:
    return os.getenv("ENABLE_UNITY_CATALOG_TESTS", "false").lower() == "true"


def is_serverless() -> bool:
    return os.getenv("ENABLE_SERVERLESS_TESTS", "false").lower() == "true"


