# This function will be called in `pyspark` script as well,
# so this should be available without a running Spark.
# If move or rename, please update the script too.
def spark_connect_mode() -> str:
    """
    Return the env var SPARK_CONNECT_MODE; otherwise "1" if `pyspark_connect` is available.
    """
    connect_by_default = os.environ.get("SPARK_CONNECT_MODE")
    if connect_by_default is not None:
        return connect_by_default
    try:
        import pyspark_connect  # noqa: F401

        return "1"
    except ImportError:
        return "0"


def default_api_mode() -> str:
    """
    Return the default API mode.
    """
    if spark_connect_mode() == "1":
        return "connect"
    else:
        return "classic"


class _FaulthandlerHelper:
    def __init__(self) -> None:
        self._log_path: Optional[str] = None
        self._use_stderr = False # EDGE
        self._log_file: Optional[TextIO] = None
        self._periodic_traceback = False
        self._reentry_depth = 0
        self._react_on_sigquit: Optional[str] = None # EDGE
        self._sigquit_handler_file: Optional[TextIO] = None # EDGE
        self._sigquit_handler_filename: Optional[str] = None # EDGE
        self._sigquit_dump_file : Optional[TextIO] = None # EDGE

    def _sigquit_handler(self, signum, frame):
        """
        Python-level SIGQUIT handler. Only dumps when active (between start/stop).

        This handler runs in the main thread with the GIL held.
        """
        dump_file = self._sigquit_dump_file 
        if dump_file is not None:
            try:
                # Using signal.signal() with explicit dump_traceback
                # instead of faulthandler.register() ensures the GIL is
                # held when the traceback is captured, avoiding potential segfaults.
                faulthandler.dump_traceback(file=dump_file, all_threads=True)
            except Exception:
                # The file may have been closed by stop() between our check and the
                # dump call. This is a benign race — just skip the dump.
                pass

    def register_sigquit_handler(self) -> None:
        """
        Register the SIGQUIT signal handler if the PYTHON_FAULTHANDLER_SIGQUIT env var is set.

        MUST be called from the main thread. Otherwise, this is a NOOP.
        Idempotent — safe to call multiple times.

        Uses signal.signal() which requires the GIL to dispatch, making thread dumps safe.

        In most entry points (worker.py, daemon.py, sql/worker/*.py), start() is called
        from the main thread and will call this function automatically. For entry points
        where start() runs in a non-main thread (e.g. workerwrap.py with isolation), this must
        be called explicitly from the main thread before spawning worker threads.
        """
        # signal.signal() can only be called from the main thread.
        if threading.current_thread() is not threading.main_thread():
            return

        react_on_sigquit = os.environ.get("PYTHON_FAULTHANDLER_SIGQUIT", None)
        if not react_on_sigquit:
            return
        
        # Register the signal
        signal.signal(signal.SIGQUIT, self._sigquit_handler)
    
    def unregister_sigquit_handler(self) -> None:
        """
        Unregisteres the SIGQUIT signal handler.

        MUST be called from the main thread. Otherwise, this is a NOOP.
        Idempotent — safe to call multiple times.
        """
        # signal.signal() can only be called from the main thread.
        if threading.current_thread() is not threading.main_thread():
            return

        # Unregister the signal
        signal.signal(signal.SIGQUIT, signal.SIG_DFL)
        
    # END EDGE

    def start(self) -> None:
        self._reentry_depth += 1
        if self._log_path:
            # faulthandler is already enabled
            return
        self._log_path = os.environ.get("PYTHON_FAULTHANDLER_DIR", None)
        self._use_stderr = os.environ.get("PYTHON_FAULTHANDLER_USE_STDERR", False) # EDGE
        self._react_on_sigquit = os.environ.get("PYTHON_FAULTHANDLER_SIGQUIT", None) # EDGE
        if self._log_path:
            self._log_path = os.path.join(self._log_path, str(os.getpid()))
            self._log_file = open(self._log_path, "w")

            faulthandler.enable(file=self._log_file)
        # BEGIN EDGE
        elif self._use_stderr:
            faulthandler.enable(file=sys.stderr)

        if self._react_on_sigquit:
            # Try to register the handler
            # -> This is idempotent and will
            # only work if being called from
            # the main thread
            self.register_sigquit_handler()

            # Configure the dump target file.
            if self._react_on_sigquit == 'stdout':
                self._sigquit_dump_file = sys.stdout
            elif self._react_on_sigquit.startswith('path:'):
                self._sigquit_handler_filename = os.path.join(
                    self._react_on_sigquit[len('path:'):],
                    "thread_dump_{}".format(os.getpid()),
                )
                try:
                    self._sigquit_handler_file = open(self._sigquit_handler_filename, "wb", buffering=0)
                    self._sigquit_dump_file = self._sigquit_handler_file
                except Exception as e:
                    # Failed to create the dump file.
                    # The handler will not be set to active
                    # -> The signal handler will be a no-op.
                    print("Failed to create handler file for sigquit handler: {}".format(e))
                    self._sigquit_dump_file = None
                    return
        # END EDGE

    def stop(self) -> None:
        self._reentry_depth -= 1
        if self._reentry_depth > 0:
            return
        if self._log_path:
            faulthandler.disable()
            if self._log_file:
                self._log_file.close()
                self._log_file = None
            try:
                os.remove(self._log_path)
            finally:
                self._log_path = None
                self._use_stderr = None # EDGE
        # BEGIN EDGE
        elif self._use_stderr:
            faulthandler.disable()
            self._use_stderr = False

        if self._react_on_sigquit:
            self.unregister_sigquit_handler()
            self._sigquit_dump_file = None
            if self._sigquit_handler_file:
                self._sigquit_handler_file.close()
                self._sigquit_handler_file = None
            if self._sigquit_handler_filename:
                try:
                    os.remove(self._sigquit_handler_filename)
                except Exception as e:
                    print("Failed to remove sigquit handler file: {}".format(e))
                finally:
                    self._sigquit_handler_filename = None
            self._react_on_sigquit = False
        # END EDGE
        if self._periodic_traceback:
            faulthandler.cancel_dump_traceback_later()
            self._periodic_traceback = False

    def start_periodic_traceback(self) -> None:
        # If the registration is already done - do nothing
        if self._periodic_traceback:
            return

        traceback_dump_interval_seconds = os.environ.get(
            "PYTHON_TRACEBACK_DUMP_INTERVAL_SECONDS", None
        )
        if traceback_dump_interval_seconds is not None and int(traceback_dump_interval_seconds) > 0:
            self._periodic_traceback = True
            faulthandler.dump_traceback_later(int(traceback_dump_interval_seconds), repeat=True)

    def with_faulthandler(self, func: Callable) -> Callable:
        """
        Registers fault handler for the duration of function execution.
        After function execution is over the faulthandler registration is cleaned as well,
        including any files created for the integration.
        """

        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            try:
                self.start()
                return func(*args, **kwargs)
            finally:
                self.stop()

        return wrapper

    @contextmanager
    def enable_faulthandler(self, start_periodic_traceback: bool = True) -> Iterator[None]:
        try:
            self.start()
            if start_periodic_traceback:
                self.start_periodic_traceback()
            yield
        finally:
            self.stop()


_faulthandler_helper = _FaulthandlerHelper()
with_faulthandler = _faulthandler_helper.with_faulthandler
start_faulthandler_periodic_traceback = _faulthandler_helper.start_periodic_traceback
enable_faulthandler = _faulthandler_helper.enable_faulthandler
register_sigquit_handler = _faulthandler_helper.register_sigquit_handler  # EDGE
unregister_sigquit_handler = _faulthandler_helper.unregister_sigquit_handler  # EDGE

if __name__ == "__main__":
    import doctest
    import pyspark.util
    from pyspark.core.context import SparkContext

    globs = pyspark.util.__dict__.copy()
    globs["sc"] = SparkContext("local[4]", "PythonTest")
    failure_count, test_count = doctest.testmod(pyspark.util, globs=globs)
    globs["sc"].stop()

    if failure_count:
        sys.exit(-1)
